import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    // Open-addressing count table for 26-bit masks (keys stored as mask + 1, 0 = empty).
    static int[] keys;
    static long[] vals;
    static int cap;
    static long seed;

    static int slot(int key) {
        long z = key + seed;
        z = (z ^ (z >>> 30)) * 0xbf58476d1ce4e5b9L;
        z = (z ^ (z >>> 27)) * 0x94d049bb133111ebL;
        z ^= z >>> 31;
        int i = (int) z & (cap - 1);
        while (keys[i] != 0 && keys[i] != key + 1) i = (i + 1) & (cap - 1);
        return i;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        int[] eu = new int[m], ev = new int[m], ew = new int[m], deg = new int[n + 1];
        for (int i = 0; i < m; i++) {
            eu[i] = (int) nextLong() - 1;
            ev[i] = (int) nextLong() - 1;
            ew[i] = (int) nextLong() - 1;
            deg[eu[i] + 1]++;
            deg[ev[i] + 1]++;
        }
        for (int i = 0; i < n; i++) deg[i + 1] += deg[i];
        int[] pos = Arrays.copyOf(deg, n), adjTo = new int[2 * m], adjW = new int[2 * m];
        for (int i = 0; i < m; i++) {
            adjTo[pos[eu[i]]] = ev[i];
            adjW[pos[eu[i]]++] = ew[i];
            adjTo[pos[ev[i]]] = eu[i];
            adjW[pos[ev[i]]++] = ew[i];
        }
        // Parity mask of letters on the root-to-node path, built in BFS order.
        int[] parent = new int[n], mask = new int[n], order = new int[n];
        Arrays.fill(parent, -1);
        parent[0] = 0;
        int size = 1;
        for (int i = 0; i < size; i++) {
            int u = order[i];
            for (int e = deg[u]; e < deg[u + 1]; e++) {
                int v = adjTo[e];
                if (v != parent[u]) {
                    parent[v] = u;
                    mask[v] = mask[u] ^ (1 << adjW[e]);
                    order[size++] = v;
                }
            }
        }
        cap = Integer.highestOneBit(Math.max(4 * n, 16)) * 2;
        keys = new int[cap];
        vals = new long[cap];
        seed = System.nanoTime();
        long answer = 0;
        // A pair is nice when the two masks are equal or differ in exactly one bit.
        for (int i = 0; i < size; i++) {
            int x = mask[order[i]];
            answer += vals[slot(x)];
            for (int b = 0; b < 26; b++) answer += vals[slot(x ^ (1 << b))];
            int s = slot(x);
            keys[s] = x + 1;
            vals[s]++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type edge struct{ to, w int32 }

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	adj := make([][]edge, n)
	for i := 0; i < m; i++ {
		u, v, w := int32(nextInt()-1), int32(nextInt()-1), int32(nextInt()-1)
		adj[u] = append(adj[u], edge{v, w})
		adj[v] = append(adj[v], edge{u, w})
	}
	// Parity mask of letters on the root-to-node path, built in BFS order.
	parent, mask := make([]int32, n), make([]int32, n)
	for i := range parent {
		parent[i] = -1
	}
	parent[0] = 0
	order := []int32{0}
	for i := 0; i < len(order); i++ {
		u := order[i]
		for _, e := range adj[u] {
			if e.to != parent[u] {
				parent[e.to] = u
				mask[e.to] = mask[u] ^ (1 << e.w)
				order = append(order, e.to)
			}
		}
	}
	seen := make(map[int32]int64, n)
	var answer int64
	// A pair is nice when the two masks are equal or differ in exactly one bit.
	for _, u := range order {
		x := mask[u]
		answer += seen[x]
		for b := 0; b < 26; b++ {
			answer += seen[x^(1<<b)]
		}
		seen[x]++
	}
	fmt.Println(answer)
}
